o=rows(ours); u=rows(up)
print('ours-only', sorted(set(o)-set(u)))
print('up-only', sorted(set(u)-set(o)))
for k in sorted(set(o)&set(u)):
 if o[k]"'!=u[k]: print('"'diff',k,'ours=',o[k],'up=',u[k])
PY"

